window.MGProseData("ab4405fb8e1d9f90ddf94b171c97ff61329eac42f8a2320709b14eca4a9fb338",{"html":"\u003cp>下面给出该四相材料零边界单元问题的完整数学证明与构造。\u003c/p>\n\u003chr>\n\u003ch3>一、 核心结论概述\u003c/h3>\n\u003cp>对于所给的四个对角应变井：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_1 = \\operatorname{diag}(3,0),\\quad A_2 = \\operatorname{diag}(1,2),\\quad A_3 = \\operatorname{diag}(-2,1),\\quad A_4 = \\operatorname{diag}(0,-3),\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n允许位移类为：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi>W\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>:\u003c/mo>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmrow>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">ess sup\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmn>4\u003c/mn>\u003cmo fence=\"true\">}\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathcal{A} = \\left\\{u \\in W^{1,\\infty}(\\Omega;\\mathbb{R}^2) : u|_{\\partial\\Omega} = 0,\\ \\operatorname{ess\\,sup}_\\Omega \\|\\nabla u\\|_F \\le 4\\right\\},\\quad \\Omega = (0,1)^2,\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n能量定义为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmsub>\u003cmrow>\u003cmi>min\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>i\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E(u) = \\int_\\Omega \\min_{1 \\le i \\le 4} \\|\\nabla u(x) - A_i\\|_F^2 \\,dx\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi>inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e_0 = \\inf_{u \\in \\mathcal{A}} E(u)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>前期的相容性计算虽然正确地指出了六个两井之差的行列式均非零（即任意两井之间均无直接的秩一连接，二相层合无法发生），但\u003cstrong>二相刚性不能直接推广到四相系统\u003c/strong>。这四个井恰好构成了变分法与微结构理论中著名的 \u003cstrong>Tartar \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T_4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 构型\u003c/strong>（Tartar 1979 / Šverák 1993 / Müller 1999）：虽然井与井之间没有秩一连接（秩一凸包 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>K\u003c/mi>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmi>c\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K^{rc} = K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>），但通过四个辅助矩阵可构成一个首尾闭合的循环相容层合链，从而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 属于其拟凸包（\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi>K\u003c/mi>\u003cmrow>\u003cmi>q\u003c/mi>\u003cmi>c\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0 \\in K^{qc}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）。\u003c/p>\n\u003cp>由此得出本题的全部结论：\u003c/p>\n\u003col>\n\u003cli>\u003cstrong>单元能的精确值为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e_0 = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/strong>；该极小值在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathcal{A}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中\u003cstrong>不可达\u003c/strong>（不存在极小元）。\u003c/li>\n\u003cli>对任意满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>→\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E(u_j) \\to e_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的序列，相体积分数向量 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(\\pi_1(u_j), \\dots, \\pi_4(u_j))\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> \u003cstrong>必然收敛到同一个向量\u003c/strong>，唯一的极限为：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmunder>\u003cmrow>\u003cmi>lim\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>10\u003c/mn>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>10\u003c/mn>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>10\u003c/mn>\u003c/mfrac>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>10\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0.1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0.3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0.3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0.3\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\lim_{j \\to \\infty} (\\pi_1(u_j), \\pi_2(u_j), \\pi_3(u_j), \\pi_4(u_j)) = \\left(\\frac{1}{10},\\, \\frac{3}{10},\\, \\frac{3}{10},\\, \\frac{3}{10}\\right) = (0.1, 0.3, 0.3, 0.3).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/li>\n\u003cli>可显式构造具细微尺度循环层合与边界层截断的近最优位移场，严格满足零边界条件、统一梯度界 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>u\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo>+\u003c/mo>\u003cmi>o\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|\\nabla u\\|_F \\le 3 + o(1) \\le 4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并使能量任意接近 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003c/ol>\n\u003chr>\n\u003ch3>二、 任务一：\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的精确值与不可达性证明\u003c/h3>\n\u003ch4>1. 精确值 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e_0 = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/h4>\n\u003cp>由于对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u \\in \\mathcal{A}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，被积函数为非负距离平方，故显然 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E(u) \\ge 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，从而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e_0 \\ge 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\n另一方面，由任务三中给出的显式位移场构造，对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ε\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon \u0026gt; 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，存在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>ε\u003c/mi>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_\\varepsilon \\in \\mathcal{A}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使得 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>ε\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>ε\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E(u_\\varepsilon) \u0026lt; \\varepsilon\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\n因此：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e_0 = \\inf_{u \\in \\mathcal{A}} E(u) = 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003ch4>2. 不可达性证明（不存在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u \\in \\mathcal{A}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使得 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E(u) = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）\u003c/h4>\n\u003cp>用反证法。假设存在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u \\in \\mathcal{A}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 达到极小值，即 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E(u) = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>因为被积函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi>min\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>i\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\min_{1 \\le i \\le 4} \\|\\nabla u(x) - A_i\\|_F^2 \\ge 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，积分值为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 意味着对几乎处处的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x \\in \\Omega\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmi>K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nabla u(x) \\in K = \\{A_1, A_2, A_3, A_4\\}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>注意到四个应变井 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_1, A_2, A_3, A_4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 全部是对角矩阵：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsub>\u003cmi>b\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>4.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i = \\begin{pmatrix} a_i \u0026amp; 0 \\\\ 0 \u0026amp; b_i \\end{pmatrix},\\quad i=1,2,3,4.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n将其写成分量：设 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u(x) = (u_1(x_1, x_2), u_2(x_1, x_2))\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则梯度的非对角元为：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmtext>a.e.\u003c/mtext>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmtext>a.e.\u003c/mtext>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\partial_2 u_1(x_1, x_2) = 0 \\quad \\text{a.e.},\\qquad \\partial_1 u_2(x_1, x_2) = 0 \\quad \\text{a.e.}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于区域 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Omega = (0,1)^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是连通开集，这表明：\u003c/p>\n\u003cul>\n\u003cli>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 几乎处处仅依赖于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，即存在一维局部 Lipschitz 函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使得 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_1(x_1, x_2) = f(x_1)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> a.e.；\u003c/li>\n\u003cli>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 几乎处处仅依赖于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，即存在一维局部 Lipschitz 函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>g\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使得 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>g\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_2(x_1, x_2) = g(x_2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> a.e.。\u003c/li>\n\u003c/ul>\n\u003cp>因此，梯度的形式必为：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsup>\u003cmi>f\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsup>\u003cmi>g\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmspace width=\"1em\"/>\u003cmtext>a.e. in \u003c/mtext>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nabla u(x_1, x_2) = \\begin{pmatrix} f\u0026#x27;(x_1) \u0026amp; 0 \\\\ 0 \u0026amp; g\u0026#x27;(x_2) \\end{pmatrix} \\quad \\text{a.e. in } \\Omega.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对几乎处处的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(x_1, x_2) \\in (0,1)^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，必须满足：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>f\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsup>\u003cmi>g\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(f\u0026#x27;(x_1), g\u0026#x27;(x_2)) \\in \\{(3,0), (1,2), (-2,1), (0,-3)\\}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>根据 Fubini 定理，固定一个使得 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>f\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u0026#x27;(x_1)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 存在的横坐标 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\n观察四个井的第一主应变（第一个对角元）：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a_1 = 3,\\quad a_2 = 1,\\quad a_3 = -2,\\quad a_4 = 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这四个数值\u003cstrong>互不相同\u003c/strong>。\n因此，对于选定的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>f\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u0026#x27;(x_1)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 最多只能与集合 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{3, 1, -2, 0\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中的\u003cstrong>某一个数\u003c/strong>相等。\n这就意味着在集合 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中，\u003cstrong>至多只有一个点\u003c/strong>的第一个分量等于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>f\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u0026#x27;(x_1)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\n从而对应几乎处处所有的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>g\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g\u0026#x27;(x_2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 只能取由该唯一匹配确定的那个常数值，不能随 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 变动。\n同理，反过来对称可得 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>f\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u0026#x27;(x_1)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 也必须为常数。\u003c/p>\n\u003cp>故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nabla u(x)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Omega\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上几乎处处为常数矩阵：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≡\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi>K\u003c/mi>\u003cmspace width=\"1em\"/>\u003cmtext>a.e.\u003c/mtext>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nabla u(x) \\equiv C \\in K \\quad \\text{a.e.}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi>W\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u \\in W^{1,\\infty}(\\Omega;\\mathbb{R}^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\partial\\Omega\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上的迹为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，由高斯散度定理（或分部积分）：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>u\u003c/mi>\u003cmo>⊗\u003c/mo>\u003cmi>ν\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>σ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\int_\\Omega \\nabla u(x) \\,dx = \\int_{\\partial\\Omega} u \\otimes \\nu \\,d\\sigma = 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此该常数矩阵必须为：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/mfrac>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C = \\frac{1}{|\\Omega|} \\int_\\Omega \\nabla u(x) \\,dx = 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n然而，零矩阵 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0 \\notin K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>（四个井的 Frobenius 范数分别为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsqrt>\u003cmn>5\u003c/mn>\u003c/msqrt>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsqrt>\u003cmn>5\u003c/mn>\u003c/msqrt>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">3, \\sqrt{5}, \\sqrt{5}, 3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，均不为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）。这产生矛盾！\u003c/p>\n\u003cp>故不存在任何 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u \\in \\mathcal{A}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 能使 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E(u) = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003cstrong>极小值 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e_0 = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 不可达。\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch3>三、 任务二：极小化序列相体积分数的唯一极限证明\u003c/h3>\n\u003cp>设 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo>⊂\u003c/mo>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{u_j\\}_{j=1}^\\infty \\subset \\mathcal{A}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为任意满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>→\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E(u_j) \\to 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的序列。我们将证明其相体积分数向量 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(\\pi_1(u_j), \\dots, \\pi_4(u_j))\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 必收敛于唯一向量 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0.1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0.3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0.3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0.3\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(0.1, 0.3, 0.3, 0.3)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003ch4>1. 分区与阶梯矩阵场近似\u003c/h4>\n\u003cp>按最近井规则，对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>j\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Omega\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 被划分为四个互不相交的可测集：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>x\u003c/mi>\u003cmtext> 被分配给 \u003c/mtext>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo fence=\"true\">}\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>4.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E_i^{(j)} = \\left\\{x \\in \\Omega : x \\text{ 被分配给 } A_i\\right\\},\\quad i=1,2,3,4.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由定义可知：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsubsup>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msubsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmn>4\u003c/mn>\u003c/munderover>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\pi_i(u_j) = |E_i^{(j)}|,\\quad \\sum_{i=1}^4 \\pi_i(u_j) = |\\Omega| = 1.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n定义分片常值矩阵场 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsubsup>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmn>4\u003c/mn>\u003c/msubsup>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmn mathvariant=\"bold\">1\u003c/mn>\u003cmsubsup>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msubsup>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V_j(x) = \\sum_{i=1}^4 A_i \\mathbf{1}_{E_i^{(j)}}(x)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。根据能量定义：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmrow>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo>×\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmn>4\u003c/mn>\u003c/munderover>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmsubsup>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msubsup>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>→\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|\\nabla u_j - V_j\\|_{L^2(\\Omega;\\mathbb{R}^{2\\times 2})}^2 = \\sum_{i=1}^4 \\int_{E_i^{(j)}} \\|\\nabla u_j(x) - A_i\\|_F^2 \\,dx = E(u_j) \\to 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n根据容许集条件，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">ess sup\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{ess\\,sup}_\\Omega \\|\\nabla u_j\\|_F \\le 4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；同时对所有的井，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|A_i\\|_F \\le 3 \u0026lt; 4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nabla u_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">L^\\infty(\\Omega)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中均被常数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 统一控制。\u003c/p>\n\u003ch4>2. 平均梯度约束（零边界条件）\u003c/h4>\n\u003cp>由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>W\u003c/mi>\u003cmn>0\u003c/mn>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_j \\in W_0^{1,\\infty}(\\Omega;\\mathbb{R}^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，平均梯度恒等于零：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\int_\\Omega \\nabla u_j(x) \\,dx = 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n利用 Cauchy-Schwarz 不等式：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmo fence=\"true\">∥\u003c/mo>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo fence=\"true\">∥\u003c/mo>\u003c/mrow>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmo fence=\"true\">∥\u003c/mo>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo fence=\"true\">∥\u003c/mo>\u003c/mrow>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\left\\| \\int_\\Omega V_j(x) \\,dx \\right\\|_F = \\left\\| \\int_\\Omega (V_j - \\nabla u_j) \\,dx \\right\\|_F \\le \\|\\nabla u_j - V_j\\|_{L^1} \\le \\|\\nabla u_j - V_j\\|_{L^2} \\to 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V_j(x)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的积分为：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmn>4\u003c/mn>\u003c/munderover>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmn>3\u003c/mn>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\int_\\Omega V_j(x) \\,dx = \\sum_{i=1}^4 \\pi_i(u_j) A_i = \\operatorname{diag}\\left(3\\pi_1(u_j) + \\pi_2(u_j) - 2\\pi_3(u_j), \\quad 2\\pi_2(u_j) + \\pi_3(u_j) - 3\\pi_4(u_j)\\right).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">j \\to \\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，得到两个渐近方程：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmunder>\u003cmrow>\u003cmi>lim\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmrow>\u003cmo fence=\"true\">[\u003c/mo>\u003cmn>3\u003c/mn>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo fence=\"true\">]\u003c/mo>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\lim_{j \\to \\infty} \\left[ 3\\pi_1(u_j) + \\pi_2(u_j) - 2\\pi_3(u_j) \\right] = 0,\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmunder>\u003cmrow>\u003cmi>lim\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmrow>\u003cmo fence=\"true\">[\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo fence=\"true\">]\u003c/mo>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\lim_{j \\to \\infty} \\left[ 2\\pi_2(u_j) + \\pi_3(u_j) - 3\\pi_4(u_j) \\right] = 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003ch4>3. 行列式约束（零拉格朗日量 Null-Lagrangian）\u003c/h4>\n\u003cp>在二维空间中，行列式 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\det(\\nabla u)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 具有发散形式：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\det(\\nabla u) = \\partial_1(u_1 \\partial_2 u_2) - \\partial_2(u_1 \\partial_1 u_2).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmrow>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_j|_{\\partial\\Omega} = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，由散度定理，\u003cstrong>对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u_j \\in \\mathcal{A}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 均严格有\u003c/strong>：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\int_\\Omega \\det(\\nabla u_j(x)) \\,dx = 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n注意到映射 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>↦\u003c/mo>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M \\mapsto \\det(M)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在有界球 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B_F(0,4)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上是局部 Lipschitz 的：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>N\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>C\u003c/mi>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>N\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi mathvariant=\"normal\">∀\u003c/mi>\u003cmi>M\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>N\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\det(M) - \\det(N)| \\le C \\|M - N\\|_F,\\quad \\forall M, N \\in B_F(0,4).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n从而：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmrow>\u003cmo fence=\"true\">∣\u003c/mo>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo fence=\"true\">∣\u003c/mo>\u003c/mrow>\u003cmo>≤\u003c/mo>\u003cmi>C\u003c/mi>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>C\u003c/mi>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\left| \\int_\\Omega \\det(V_j(x)) \\,dx - \\int_\\Omega \\det(\\nabla u_j(x)) \\,dx \\right| \\le C \\int_\\Omega \\|\\nabla u_j - V_j\\|_F \\,dx \\le C \\|\\nabla u_j - V_j\\|_{L^2} \\to 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmunder>\u003cmrow>\u003cmi>lim\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\lim_{j \\to \\infty} \\int_\\Omega \\det(V_j(x)) \\,dx = 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n将 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在各子集上的取值代入：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmn>4\u003c/mn>\u003c/munderover>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\int_\\Omega \\det(V_j(x)) \\,dx = \\sum_{i=1}^4 \\pi_i(u_j) \\det(A_i).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n直接计算四个井的行列式：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo>×\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\det(A_1) = 3 \\times 0 = 0,\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>×\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\det(A_2) = 1 \\times 2 = 2,\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo>×\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\det(A_3) = -2 \\times 1 = -2,\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo>×\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\det(A_4) = 0 \\times (-3) = 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n于是：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmo>∫\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>d\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>→\u003c/mo>\u003cmn>0\u003c/mn>\u003cmtext>  \u003c/mtext>\u003cmo>⟹\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmunder>\u003cmrow>\u003cmi>lim\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>j\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\int_\\Omega \\det(V_j(x)) \\,dx = 2 \\pi_2(u_j) - 2 \\pi_3(u_j) \\to 0 \\implies \\lim_{j \\to \\infty} [\\pi_2(u_j) - \\pi_3(u_j)] = 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003ch4>4. 极限方程组的唯一解\u003c/h4>\n\u003cp>由于序列 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>u\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(\\pi_1(u_j), \\dots, \\pi_4(u_j))\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 包含在紧集 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Δ\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msup>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>∑\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Delta_4 = \\{\\lambda \\in \\mathbb{R}^4 : \\lambda_i \\ge 0, \\sum \\lambda_i = 1\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中，任何子列极限 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>λ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>T\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\lambda = (\\lambda_1, \\lambda_2, \\lambda_3, \\lambda_4)^T\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都必须满足联立线性方程组：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmtext>总体积为 \u003c/mtext>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>3\u003c/mn>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmtext>平均梯度 \u003c/mtext>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> 元为 \u003c/mtext>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmtext>平均梯度 \u003c/mtext>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext> 元为 \u003c/mtext>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmtext>平均行列式为 \u003c/mtext>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\begin{cases}\n\\lambda_1 + \\lambda_2 + \\lambda_3 + \\lambda_4 = 1 \u0026amp; (\\text{总体积为 } 1) \\\\\n3\\lambda_1 + \\lambda_2 - 2\\lambda_3 = 0 \u0026amp; (\\text{平均梯度 } (1,1) \\text{ 元为 } 0) \\\\\n2\\lambda_2 + \\lambda_3 - 3\\lambda_4 = 0 \u0026amp; (\\text{平均梯度 } (2,2) \\text{ 元为 } 0) \\\\\n\\lambda_2 - \\lambda_3 = 0 \u0026amp; (\\text{平均行列式为 } 0)\n\\end{cases}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n写成矩阵形式 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmi>λ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>b\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M \\lambda = b\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>3\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>b\u003c/mi>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M = \\begin{pmatrix} 1 \u0026amp; 1 \u0026amp; 1 \u0026amp; 1 \\\\ 3 \u0026amp; 1 \u0026amp; -2 \u0026amp; 0 \\\\ 0 \u0026amp; 2 \u0026amp; 1 \u0026amp; -3 \\\\ 0 \u0026amp; 1 \u0026amp; -1 \u0026amp; 0 \\end{pmatrix},\\quad b = \\begin{pmatrix} 1 \\\\ 0 \\\\ 0 \\\\ 0 \\end{pmatrix}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n计算系数矩阵的行列式：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>⋅\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">∣\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">∣\u003c/mo>\u003c/mrow>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo>⋅\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">∣\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">∣\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\det(M) = 1 \\cdot \\begin{vmatrix} 1 \u0026amp; -2 \u0026amp; 0 \\\\ 2 \u0026amp; 1 \u0026amp; -3 \\\\ 1 \u0026amp; -1 \u0026amp; 0 \\end{vmatrix} - 3 \\cdot \\begin{vmatrix} 1 \u0026amp; 1 \u0026amp; 1 \\\\ 2 \u0026amp; 1 \u0026amp; -3 \\\\ 1 \u0026amp; -1 \u0026amp; 0 \\end{vmatrix}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对第一个小行列式按第三列展开：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⋅\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>3.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">-(-3) \\cdot [1(-1) - (-2)(1)] = 3(1) = 3.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对第二个小行列式：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>3.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1(0 - (-3)) - 1(0 - (-3)) + 1(-2 - 1) = 3 - 3 - 3 = -3.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n从而：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>12\u003c/mn>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\det(M) = 3 - 3(-3) = 12 \\ne 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n矩阵 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 严格非奇异，解唯一。代入验证求解：\n由第 4 式，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\lambda_3 = \\lambda_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；\n代入第 2 式：\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>3\u003c/mn>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmtext>  \u003c/mtext>\u003cmo>⟹\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmn>3\u003c/mn>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmtext>  \u003c/mtext>\u003cmo>⟹\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">3\\lambda_1 + \\lambda_2 - 2\\lambda_2 = 0 \\implies 3\\lambda_1 = \\lambda_2 \\implies \\lambda_1 = \\frac{1}{3}\\lambda_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；\n代入第 3 式：\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmtext>  \u003c/mtext>\u003cmo>⟹\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmn>3\u003c/mn>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>3\u003c/mn>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmtext>  \u003c/mtext>\u003cmo>⟹\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\\lambda_2 + \\lambda_2 - 3\\lambda_4 = 0 \\implies 3\\lambda_4 = 3\\lambda_2 \\implies \\lambda_4 = \\lambda_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；\n代入第 1 式：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmtext>  \u003c/mtext>\u003cmo>⟹\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmfrac>\u003cmn>10\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmtext>  \u003c/mtext>\u003cmo>⟹\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>10\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{1}{3}\\lambda_2 + \\lambda_2 + \\lambda_2 + \\lambda_2 = 1 \\implies \\frac{10}{3}\\lambda_2 = 1 \\implies \\lambda_2 = \\frac{3}{10}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n从而求得唯一的极限向量：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>10\u003c/mn>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmn>0.1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>10\u003c/mn>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmn>0.3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>10\u003c/mn>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmn>0.3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>10\u003c/mn>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmn>0.3.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\lambda_1 = \\frac{1}{10} = 0.1,\\quad \\lambda_2 = \\frac{3}{10} = 0.3,\\quad \\lambda_3 = \\frac{3}{10} = 0.3,\\quad \\lambda_4 = \\frac{3}{10} = 0.3.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于紧集中每个收敛子列均收敛到该同一点，全序列必然收敛到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0.1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0.3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0.3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0.3\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(0.1, 0.3, 0.3, 0.3)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003cstrong>不存在其他极限。\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch3>四、 任务三：近最优位移的具体显式构造与验证\u003c/h3>\n\u003cp>我们构造显式的近最优位移序列 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>u\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u^{(k)} \\in \\mathcal{A}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使得当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k \\to \\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>u\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>→\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E(u^{(k)}) \\to 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003ch4>1. \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T_4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 构型的循环相容几何\u003c/h4>\n\u003cp>引入四个辅助对角矩阵：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_1 = \\operatorname{diag}(0,0),\\quad P_2 = \\operatorname{diag}(1,0),\\quad P_3 = \\operatorname{diag}(1,1),\\quad P_4 = \\operatorname{diag}(0,1).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n注意到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_1 = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 正好对应零边界条件下的平庸梯度。\u003c/p>\n\u003cp>这四个辅助矩阵与四个井之间存在精确的\u003cstrong>秩一凸分解环路\u003c/strong>（全部沿坐标轴方向）：\u003c/p>\n\u003col>\n\u003cli>\u003cstrong>从 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{A_4, P_4\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\u003c/strong>\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>4\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo>⊗\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmtext>法向 \u003c/mtext>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_1 = \\frac{1}{4} A_4 + \\frac{3}{4} P_4,\\quad P_4 - A_4 = \\operatorname{diag}(0, 4) = \\begin{pmatrix} 0 \\\\ 4 \\end{pmatrix} \\otimes e_2 \\quad (\\text{法向 } e_2=(0,1))\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/li>\n\u003cli>\u003cstrong>从 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{A_3, P_3\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\u003c/strong>\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>2\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>3\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo>⊗\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmtext>法向 \u003c/mtext>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_4 = \\frac{1}{3} A_3 + \\frac{2}{3} P_3,\\quad P_3 - A_3 = \\operatorname{diag}(3, 0) = \\begin{pmatrix} 3 \\\\ 0 \\end{pmatrix} \\otimes e_1 \\quad (\\text{法向 } e_1=(1,0))\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/li>\n\u003cli>\u003cstrong>从 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{A_2, P_2\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\u003c/strong>\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo>⊗\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmtext>法向 \u003c/mtext>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_3 = \\frac{1}{2} A_2 + \\frac{1}{2} P_2,\\quad A_2 - P_2 = \\operatorname{diag}(0, 2) = \\begin{pmatrix} 0 \\\\ 2 \\end{pmatrix} \\otimes e_2 \\quad (\\text{法向 } e_2=(0,1))\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/li>\n\u003cli>\u003cstrong>从 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{A_1, P_1\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\u003c/strong>\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmfrac>\u003cmn>2\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>3\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo>⊗\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmtext>法向 \u003c/mtext>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_2 = \\frac{1}{3} A_1 + \\frac{2}{3} P_1,\\quad A_1 - P_1 = \\operatorname{diag}(3, 0) = \\begin{pmatrix} 3 \\\\ 0 \\end{pmatrix} \\otimes e_1 \\quad (\\text{法向 } e_1=(1,0))\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/li>\n\u003c/ol>\n\u003cp>\u003cstrong>体积分数几何收缩机制：\u003c/strong>\n在一个完整循环后，未转化（仍处于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 态）的体积比率为：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>ρ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003cmo>×\u003c/mo>\u003cmfrac>\u003cmn>2\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003cmo>×\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo>×\u003c/mo>\u003cmfrac>\u003cmn>2\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>6\u003c/mn>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\rho = \\frac{3}{4} \\times \\frac{2}{3} \\times \\frac{1}{2} \\times \\frac{2}{3} = \\frac{1}{6}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在一个周期内生成的各井体积分数分别为：\u003c/p>\n\u003cul>\n\u003cli>相 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{1}{4}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；\u003c/li>\n\u003cli>相 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003cmo>×\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{3}{4} \\times \\frac{1}{3} = \\frac{1}{4}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；\u003c/li>\n\u003cli>相 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003cmo>×\u003c/mo>\u003cmfrac>\u003cmn>2\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003cmo>×\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{3}{4} \\times \\frac{2}{3} \\times \\frac{1}{2} = \\frac{1}{4}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；\u003c/li>\n\u003cli>相 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmn>3\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003cmo>×\u003c/mo>\u003cmfrac>\u003cmn>2\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003cmo>×\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo>×\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>3\u003c/mn>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>12\u003c/mn>\u003c/mfrac>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{3}{4} \\times \\frac{2}{3} \\times \\frac{1}{2} \\times \\frac{1}{3} = \\frac{1}{12}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；\u003c/li>\n\u003cli>剩余 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>6\u003c/mn>\u003c/mfrac>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\frac{1}{6}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\n对剩余的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 区域自相似递归迭代 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 次，未转化为井的区域测度指数衰减为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>6\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>k\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(1/6)^k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\n各相累积占有的体积分数比值为：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>12\u003c/mn>\u003c/mfrac>\u003cmo>:\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003cmo>:\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003cmo>:\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>:\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo>:\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo>:\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|A_1| : |A_2| : |A_3| : |A_4| = \\frac{1}{12} : \\frac{1}{4} : \\frac{1}{4} : \\frac{1}{4} = 1 : 3 : 3 : 3,\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n经归一化即为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0.1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0.3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0.3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0.3\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(0.1, 0.3, 0.3, 0.3)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003c/ul>\n\u003ch4>2. 显式位移场函数构造\u003c/h4>\n\u003cp>定义标准周期一维分段线性剖面函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>h\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h_t: \\mathbb{R} \\to \\mathbb{R}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>（以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为周期，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t \\in (0,1)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>h\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>s\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h_t(s) = \\begin{cases} (1-t)s, \u0026amp; 0 \\le s \u0026lt; t \\\\ -t(s-1), \u0026amp; t \\le s \u0026lt; 1 \\end{cases},\\quad s \\in [0,1).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其导数几乎处处为：在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(0,t)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>t\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1-t\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(t,1)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi>t\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">-t\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi>h\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|h_t(s)| \\le t(1-t) \\le \\frac{1}{4}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>若某区域原本梯度为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>t\u003c/mi>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M = (1-t)A + tB\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>⊗\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B - A = a \\otimes n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>（\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>n\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|n|=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>），则位移修正项定义为：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>M\u003c/mi>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>ε\u003c/mi>\u003cmsub>\u003cmi>h\u003c/mi>\u003cmi>t\u003c/mi>\u003c/msub>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cmi>ε\u003c/mi>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi>a\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">w(x) = M x + \\varepsilon h_t\\left(\\frac{x \\cdot n}{\\varepsilon}\\right) a.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其梯度满足：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsubsup>\u003cmi>h\u003c/mi>\u003cmi>t\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msubsup>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>⋅\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cmi>ε\u003c/mi>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi>a\u003c/mi>\u003cmo>⊗\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>B\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>B\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmtext>测度占比 \u003c/mtext>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>B\u003c/mi>\u003cmo>−\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmtext>测度占比 \u003c/mtext>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>t\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nabla w(x) = M + h_t\u0026#x27;\\left(\\frac{x \\cdot n}{\\varepsilon}\\right) a \\otimes n = \\begin{cases} M + (1-t)(B-A) = B, \u0026amp; \\text{测度占比 } t \\\\ M - t(B-A) = A, \u0026amp; \\text{测度占比 } 1-t \\end{cases}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n且位移微扰满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>w\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>M\u003c/mi>\u003cmi>x\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>4\u003c/mn>\u003c/mfrac>\u003cmi>ε\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi>a\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|w(x) - M x\\|_\\infty \\le \\frac{1}{4} \\varepsilon |a|\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003ch5>单周期内部四层层合构造\u003c/h5>\n\u003cp>设当前区域的初始梯度为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_1 = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\u003c/p>\n\u003col>\n\u003cli>\u003cstrong>第 1 层（\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_1 \\to \\{A_4, P_4\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）：\u003c/strong>\n法向为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>t\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>3\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t_1 = 3/4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>4\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>T\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a_1 = (0, 4)^T\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。选取特征尺度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon_1 \u0026gt; 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>v\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>h\u003c/mi>\u003cmrow>\u003cmn>3\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>4\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v_1(x) = \\varepsilon_1 h_{3/4}\\left(\\frac{x_2}{\\varepsilon_1}\\right) \\begin{pmatrix} 0 \\\\ 4 \\end{pmatrix}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在占比 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1/4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的水平条带上 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>v\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nabla v_1 = A_4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；在占比 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>3\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">3/4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的水平条带 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>S\u003c/mi>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">S_{P_4}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsub>\u003cmi>v\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nabla v_1 = P_4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003cli>\u003cstrong>第 2 层（\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_4 \\to \\{A_3, P_3\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）：\u003c/strong>\n在条带 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>S\u003c/mi>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">S_{P_4}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 内，引入光滑截断函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>ψ\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\psi_1(x_2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，在条带内部为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，并在边界层 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>≪\u003c/mo>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\delta_1 \\ll \\varepsilon_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 内平滑过渡到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>（满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsubsup>\u003cmi>ψ\u003c/mi>\u003cmn>1\u003c/mn>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msubsup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>C\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\psi_1\u0026#x27;| \\le C/\\delta_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）。\n选取极细尺度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>≪\u003c/mo>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon_2 \\ll \\delta_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。叠加修正：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>v\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>v\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>ψ\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>h\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>3\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v_2(x) = v_1(x) + \\psi_1(x_2) \\varepsilon_2 h_{2/3}\\left(\\frac{x_1}{\\varepsilon_2}\\right) \\begin{pmatrix} 3 \\\\ 0 \\end{pmatrix}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>ψ\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\psi_1=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的主区域上，梯度沿坚直条带精确分裂为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>（占比 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1/3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>（占比 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2/3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）。因截断产生的附加交叉梯度项为：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsubsup>\u003cmi>ψ\u003c/mi>\u003cmn>1\u003c/mn>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>h\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>C\u003c/mi>\u003cmfrac>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mfrac>\u003cmo>→\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|\\psi_1\u0026#x27;(x_2) \\varepsilon_2 h_{2/3} a_2\\| \\le C \\frac{\\varepsilon_2}{\\delta_1} \\to 0.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/li>\n\u003cli>\u003cstrong>第 3 层（\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_3 \\to \\{A_2, P_2\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）：\u003c/strong>\n同理，选取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>≪\u003c/mo>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>≪\u003c/mo>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon_3 \\ll \\delta_2 \\ll \\varepsilon_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 子区域叠加水平振荡：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>v\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>v\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>ψ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>h\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v_3(x) = v_2(x) + \\psi_2(x_1) \\varepsilon_3 h_{1/2}\\left(\\frac{x_2}{\\varepsilon_3}\\right) \\begin{pmatrix} 0 \\\\ -2 \\end{pmatrix}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在有效区域分裂为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>（占比 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1/2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）与 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>（占比 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1/2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）。\u003c/li>\n\u003cli>\u003cstrong>第 4 层（\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_2 \\to \\{A_1, P_1\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）：\u003c/strong>\n选取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo>≪\u003c/mo>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>≪\u003c/mo>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon_4 \\ll \\delta_3 \\ll \\varepsilon_3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 子区域叠加竖直振荡：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>v\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>v\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>ψ\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>h\u003c/mi>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v_4(x) = v_3(x) + \\psi_3(x_2) \\varepsilon_4 h_{2/3}\\left(\\frac{x_1}{\\varepsilon_4}\\right) \\begin{pmatrix} -3 \\\\ 0 \\end{pmatrix}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n在有效区域分裂为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>（占比 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1/3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）与剩余的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>（占比 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2/3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）。\u003c/li>\n\u003c/ol>\n\u003ch5>多周期递归与全域构建\u003c/h5>\n\u003cp>对剩余的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 连通块重复上述四步构造，共迭代 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 次，得到函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>v\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v^{(k)}(x)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\n各级尺度参数满足：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>≪\u003c/mo>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>≪\u003c/mo>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>≪\u003c/mo>\u003cmo>⋯\u003c/mo>\u003cmo>≪\u003c/mo>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon_{4m+4} \\ll \\delta_{4m+3} \\ll \\varepsilon_{4m+3} \\ll \\dots \\ll \\varepsilon_1.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由此可使各级过渡层引起的交叉导数模长总和小于任意预给小量 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>σ\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma \u0026gt; 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且过渡层测度占 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Omega\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的比率小于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>σ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\n由于每一级位移微扰均受控于其波长，全场位移满足一致小估计：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>v\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmrow>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmi>C\u003c/mi>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|v^{(k)}\\|_{L^\\infty(\\Omega)} \\le C \\varepsilon_1.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003ch5>零边界层截断\u003c/h5>\n\u003cp>引入标准边界截断函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmi>c\u003c/mi>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\eta \\in C_c^\\infty(\\Omega; [0,1])\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmtext>在 \u003c/mtext>\u003cmsub>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi mathvariant=\"normal\">dist\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmtext> 上\u003c/mtext>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>η\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmfrac>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mfrac>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\eta(x) = 1 \\quad \\text{在 } \\Omega_{\\delta_0} = \\{x \\in \\Omega : \\operatorname{dist}(x, \\partial\\Omega) \\ge \\delta_0\\} \\text{ 上},\\quad |\\nabla \\eta| \\le \\frac{C_0}{\\delta_0}.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n定义最终近最优位移场为：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>u\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>η\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsup>\u003cmi>v\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u^{(k)}(x) = \\eta(x) v^{(k)}(x).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003ch4>3. 约束与能量估计的严格验证\u003c/h4>\n\u003ch5>(1) 零边界条件\u003c/h5>\n\u003cp>因 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>η\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsubsup>\u003cmi>C\u003c/mi>\u003cmi>c\u003c/mi>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\eta \\in C_c^\\infty(\\Omega)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\partial\\Omega\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的邻域内恒为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>u\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi>W\u003c/mi>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmo separator=\"true\">;\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u^{(k)} \\in W^{1,\\infty}(\\Omega;\\mathbb{R}^2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∂\u003c/mi>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\partial\\Omega\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上的迹严格为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003ch5>(2) 统一梯度上界验证\u003c/h5>\n\u003cp>计算其梯度场：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsup>\u003cmi>u\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>η\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsup>\u003cmi>v\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmi>v\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⊗\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>η\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\nabla u^{(k)}(x) = \\eta(x) \\nabla v^{(k)}(x) + v^{(k)}(x) \\otimes \\nabla \\eta(x).\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cul>\n\u003cli>在四个井及四个辅助状态处，Frobenius 范数分别为：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsqrt>\u003cmn>5\u003c/mn>\u003c/msqrt>\u003cmo>≈\u003c/mo>\u003cmn>2.236\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsqrt>\u003cmn>5\u003c/mn>\u003c/msqrt>\u003cmo>≈\u003c/mo>\u003cmn>2.236\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|A_1\\|_F = 3,\\quad \\|A_2\\|_F = \\sqrt{5} \\approx 2.236,\\quad \\|A_3\\|_F = \\sqrt{5} \\approx 2.236,\\quad \\|A_4\\|_F = 3,\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsqrt>\u003cmn>2\u003c/mn>\u003c/msqrt>\u003cmo>≈\u003c/mo>\u003cmn>1.414\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|P_1\\|_F = 0,\\quad \\|P_2\\|_F = 1,\\quad \\|P_3\\|_F = \\sqrt{2} \\approx 1.414,\\quad \\|P_4\\|_F = 1.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所有井与辅助矩阵的模长最大值仅为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003cli>在内部层合的过渡区域，各层交叉导数满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsup>\u003cmi>v\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>−\u003c/mo>\u003cmtext>State\u003c/mtext>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmi>σ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|\\nabla v^{(k)} - \\text{State}\\|_F \\le \\sigma\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003cli>对于边界过渡项，预先选取足够小的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon_1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使得：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>v\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>⊗\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>η\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>L\u003c/mi>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msup>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsup>\u003cmi>v\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>η\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmi>C\u003c/mi>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>⋅\u003c/mo>\u003cmfrac>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mfrac>\u003cmo>≤\u003c/mo>\u003cmi>σ\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|v^{(k)} \\otimes \\nabla \\eta\\|_{L^\\infty} \\le \\|v^{(k)}\\|_\\infty \\|\\nabla \\eta\\|_\\infty \\le C \\varepsilon_1 \\cdot \\frac{C_0}{\\delta_0} \\le \\sigma.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>σ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0.2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma = 0.2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则对几乎处处的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x \\in \\Omega\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsup>\u003cmi>u\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>max\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>i\u003c/mi>\u003c/munder>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>σ\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo>+\u003c/mo>\u003cmn>0.4\u003c/mn>\u003cmo>=\u003c/mo>\u003cmn>3.4\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmn>4.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\|\\nabla u^{(k)}(x)\\|_F \\le \\max_{i} \\|A_i\\|_F + 2\\sigma \\le 3 + 0.4 = 3.4 \\le 4.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n严格满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">ess sup\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmsup>\u003cmi>u\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{ess\\,sup}_\\Omega \\|\\nabla u^{(k)}\\|_F \\le 4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003c/ul>\n\u003ch5>(3) 能量估计\u003c/h5>\n\u003cp>将区域 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Omega\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 划分为三部分：\u003c/p>\n\u003col>\n\u003cli>\u003cstrong>纯相有效区 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmtext>wells\u003c/mtext>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Omega_{\\text{wells}}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/strong>：梯度已落入四个井的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>σ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-邻域内，能量密度不超过 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>σ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003cli>\u003cstrong>剩余未转化区 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmtext>rem\u003c/mtext>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Omega_{\\text{rem}}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/strong>：梯度仍处于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_1 = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>σ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-邻域内。其测度为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmtext>rem\u003c/mtext>\u003c/msub>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>6\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>k\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">|\\Omega_{\\text{rem}}| \\le (1/6)^k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\n在该区域内，距离最近的井为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 或 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmunder>\u003cmrow>\u003cmi>min\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>i\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmn>4\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmn>0\u003c/mn>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsubsup>\u003cmi mathvariant=\"normal\">∥\u003c/mi>\u003cmi>F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmi>min\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmn>9\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>5\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>5\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>9\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>5.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\min_{1 \\le i \\le 4} \\|0 - A_i\\|_F^2 = \\min\\{9, 5, 5, 9\\} = 5.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n能量贡献不超过 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>5\u003c/mn>\u003cmo>+\u003c/mo>\u003cmi>O\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>σ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⋅\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>6\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>k\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(5 + O(\\sigma)) \\cdot (1/6)^k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003cli>\u003cstrong>边界与过渡层 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmtext>trans\u003c/mtext>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\Omega_{\\text{trans}}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/strong>：包括外边界层（测度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>O\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">O(\\delta_0)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）和各层合内部过渡层（测度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>O\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>σ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">O(\\sigma)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>）。\n在该区域上，梯度模长受控于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，被积函数受控于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>4\u003c/mn>\u003cmo>+\u003c/mo>\u003cmn>3\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmn>49\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(4 + 3)^2 = 49\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。其总能量贡献为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>49\u003c/mn>\u003cmo>⋅\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>O\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi>O\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>σ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">49 \\cdot (O(\\delta_0) + O(\\sigma))\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003c/ol>\n\u003cp>综合以上三部分：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>u\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsup>\u003cmi>σ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmi mathvariant=\"normal\">Ω\u003c/mi>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>6\u003c/mn>\u003cmsup>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>6\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi>k\u003c/mi>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmn>49\u003c/mn>\u003cmo>⋅\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>C\u003c/mi>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmi>σ\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E(u^{(k)}) \\le \\sigma^2 |\\Omega| + 6 \\left(\\frac{1}{6}\\right)^k + 49 \\cdot [C \\delta_0 + \\sigma].\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对任意给定的容许误差 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ε\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon \u0026gt; 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\u003c/p>\n\u003cul>\n\u003cli>首先选取充分大的循环次数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使得 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>6\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>6\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>k\u003c/mi>\u003c/msup>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>ε\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">6(1/6)^k \u0026lt; \\varepsilon / 3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；\u003c/li>\n\u003cli>其次选取充分小的边界层宽度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\delta_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 和参数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>σ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使得 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>49\u003c/mn>\u003cmi>C\u003c/mi>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>ε\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">49 C \\delta_0 \u0026lt; \\varepsilon / 3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>σ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmn>49\u003c/mn>\u003cmi>σ\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>ε\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma^2 + 49 \\sigma \u0026lt; \\varepsilon / 3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；\u003c/li>\n\u003cli>最后按上述层次不等式逐级确定极细层合波长 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>ε\u003c/mi>\u003cmrow>\u003cmn>4\u003c/mn>\u003cmi>k\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon_1, \\dots, \\varepsilon_{4k}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/li>\n\u003c/ul>\n\u003cp>即得到：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>u\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>ε\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E(u^{(k)}) \u0026lt; \\varepsilon.\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这证明了 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi>inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"script\">A\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e_0 = \\inf_{u \\in \\mathcal{A}} E(u) = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>同时，在该构造中，相 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_1, A_2, A_3, A_4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 占据的主区域测度比严格为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>:\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo>:\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo>:\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1 : 3 : 3 : 3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，未分配至四个井的过渡层与剩余层测度总和为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>O\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi>O\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>σ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>6\u003c/mn>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi>k\u003c/mi>\u003c/msup>\u003cmo>→\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">O(\\delta_0) + O(\\sigma) + (1/6)^k \\to 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因此其相体积分数：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmunder>\u003cmrow>\u003cmi>lim\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>→\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>u\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>u\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>u\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>u\u003c/mi>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0.1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0.3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0.3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0.3\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\lim_{k \\to \\infty} (\\pi_1(u^{(k)}), \\pi_2(u^{(k)}), \\pi_3(u^{(k)}), \\pi_4(u^{(k)})) = (0.1, 0.3, 0.3, 0.3),\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n与任务二的理论唯一极限完全吻合。\u003c/p>\n\u003chr>\n\u003ch3>五、 结论汇总表\u003c/h3>\n\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth style=\"text-align:left\">考察项\u003c/th>\n\u003cth style=\"text-align:left\">数学结论\u003c/th>\n\u003cth style=\"text-align:left\">判定 / 极限值\u003c/th>\n\u003cth style=\"text-align:left\">核心依据\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\n\u003ctr>\n\u003ctd style=\"text-align:left\">\u003cstrong>单元能最小值 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/strong>\u003c/td>\n\u003ctd style=\"text-align:left\">精确下确界\u003c/td>\n\u003ctd style=\"text-align:left\">\u003cstrong>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e_0 = 0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/strong>\u003c/td>\n\u003ctd style=\"text-align:left\">存在高阶循环层合序列使能量趋于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>（Tartar \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T_4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 构型）\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd style=\"text-align:left\">\u003cstrong>可达性\u003c/strong>\u003c/td>\n\u003ctd style=\"text-align:left\">是否达到\u003c/td>\n\u003ctd style=\"text-align:left\">\u003cstrong>不可达\u003c/strong>（不存在极小元）\u003c/td>\n\u003ctd style=\"text-align:left\">对角梯度场必退化为常值场，零边界迫使梯级为零矩阵，而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0 \\notin K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd style=\"text-align:left\">\u003cstrong>相体积分数极限\u003c/strong>\u003c/td>\n\u003ctd style=\"text-align:left\">是否必然收敛\u003c/td>\n\u003ctd style=\"text-align:left\">\u003cstrong>必然收敛到唯一向量\u003c/strong>\u003c/td>\n\u003ctd style=\"text-align:left\">由平均梯度为零与零拉格朗日量 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>det\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∇\u003c/mi>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\det(\\nabla u)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 守恒构成的非奇异线性系统锁定\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd style=\"text-align:left\">\u003cstrong>相体积分数取值\u003c/strong>\u003c/td>\n\u003ctd style=\"text-align:left\">\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>π\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(\\pi_1, \\pi_2, \\pi_3, \\pi_4)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003ctd style=\"text-align:left\">\u003cstrong>\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0.1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>0.3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>0.3\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>0.3\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(0.1,\\, 0.3,\\, 0.3,\\, 0.3)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/strong>\u003c/td>\n\u003ctd style=\"text-align:left\">唯一解 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>10\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>λ\u003c/mi>\u003cmn>4\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>3\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>10\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\lambda_1 = 1/10,\\ \\lambda_2 = \\lambda_3 = \\lambda_4 = 3/10\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd style=\"text-align:left\">\u003cstrong>位移构造\u003c/strong>\u003c/td>\n\u003ctd style=\"text-align:left\">容许性验证\u003c/td>\n\u003ctd style=\"text-align:left\">\u003cstrong>严格成立\u003c/strong>\u003c/td>\n\u003ctd style=\"text-align:left\">$u\u003c/td>\n\u003c/tr>\n\u003c/tbody>\n\u003c/table>\n","source":"assets/content/ab4405fb8e1d9f90ddf94b171c97ff61329eac42f8a2320709b14eca4a9fb338.html"});
